// Jonker-Volgenant LAP minimization, adapted from the public-domain
// implementation by R. Jonker and A. Volgenant (University of Amsterdam),
// commonly distributed as lap.h / lap.cpp.
// Returns rowsol[i] = column assigned to row i.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <iostream>

static int lap(int dim, const double* cost, int* rowsol, int* colsol) {
    // cost is row-major dim*dim
    constexpr double INF = 1e18;
    std::vector<double> u(dim), v(dim);
    std::vector<int> free_rows(dim);
    std::vector<int> pred(dim);
    std::vector<double> d(dim);
    std::vector<char> scanned(dim);
    int nfree = 0;

    for (int i = 0; i < dim; ++i) { rowsol[i] = -1; colsol[i] = -1; }

    // COLUMN REDUCTION
    for (int j = dim - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < dim; ++i) {
            double h = cost[i * dim + j];
            if (h < minv) { minv = h; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }

    // REDUCTION TRANSFER
    for (int i = 0; i < dim; ++i) {
        int j1 = rowsol[i];
        if (j1 == -1) {
            free_rows[nfree++] = i;
        } else {
            double minv = INF;
            const double* row = cost + i * dim;
            for (int j = 0; j < dim; ++j) if (j != j1) {
                double h = row[j] - v[j];
                if (h < minv) minv = h;
            }
            v[j1] = row[j1] - minv;
        }
    }

    // AUGMENTING ROW REDUCTION
    for (int pass = 0; pass < 2; ++pass) {
        int k = 0;
        int prev = nfree;
        nfree = 0;
        while (k < prev) {
            int i = free_rows[k++];
            double umin = cost[i * dim] - v[0];
            int j1 = 0;
            double usub = INF;
            int j2 = -1;
            const double* row = cost + i * dim;
            for (int j = 1; j < dim; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            double cred = usub - umin; // >= 0
            if (umin < usub) v[j1] -= cred;
            else if (i0 != -1 && j2 != -1) { j1 = j2; i0 = colsol[j1]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 != -1) {
                if (umin < usub) free_rows[--k] = i0;
                else free_rows[nfree++] = i0;
            }
        }
    }

    // rebuild free
    nfree = 0;
    for (int i = 0; i < dim; ++i) {
        int j = rowsol[i];
        if (j < 0 || colsol[j] != i) {
            rowsol[i] = -1;
            free_rows[nfree++] = i;
        }
    }
    for (int j = 0; j < dim; ++j) {
        int i = colsol[j];
        if (i < 0 || rowsol[i] != j) colsol[j] = -1;
    }

    // AUGMENTATION
    std::vector<int> ready(dim), prev_list(dim);
    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        for (int j = 0; j < dim; ++j) {
            d[j] = cost[freerow * dim + j] - v[j];
            pred[j] = freerow;
            scanned[j] = 0;
        }
        int endofpath = -1;
        int low = 0, up = 0; // indices into ready list of columns to scan
        // initialize ready with columns of minimum d? classic uses a threshold scan
        // We'll use simple O(n^2) scan which is still C++ fast, but try the
        // "minimum d unlabeled" approach.
        while (true) {
            int jmin = -1;
            double mind = INF;
            for (int j = 0; j < dim; ++j) if (!scanned[j] && d[j] < mind) { mind = d[j]; jmin = j; }
            if (jmin < 0) break;
            scanned[jmin] = 1;
            int i = colsol[jmin];
            if (i == -1) { endofpath = jmin; break; }
            const double* row = cost + i * dim;
            double base = mind - (row[jmin] - v[jmin]);
            // h = base + row[j] - v[j]
            for (int j = 0; j < dim; ++j) if (!scanned[j]) {
                double h = base + row[j] - v[j];
                if (h < d[j]) { d[j] = h; pred[j] = i; }
            }
        }
        if (endofpath < 0) return -1;
        double delta = d[endofpath];
        for (int j = 0; j < dim; ++j) if (scanned[j]) v[j] += delta - d[j];
        // augment
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int next = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = next;
        }
    }
    return 0;
}

int main() {
    int n;
    if (!(std::cin >> n)) return 1;
    std::vector<double> C(n * n), a(n), b(n);
    for (int i = 0; i < n; ++i) std::cin >> a[i];
    for (int i = 0; i < n; ++i) std::cin >> b[i];
    for (int i = 0; i < n * n; ++i) std::cin >> C[i];
    std::vector<int> rowsol(n), colsol(n);
    clock_t t0 = clock();
    int rc = lap(n, C.data(), rowsol.data(), colsol.data());
    clock_t t1 = clock();
    std::cerr << "rc " << rc << " time " << double(t1 - t0) / CLOCKS_PER_SEC << "\n";
    // output permutation
    for (int i = 0; i < n; ++i) std::cout << rowsol[i] << (i + 1 == n ? '\n' : ' ');
    return 0;
}
