// Cost-scaling assignment (Goldberg-Kennedy style) for dense min-cost perfect matching.
// Uniform supplies. Returns a permutation. We then compare to POT.
#include <cstdint>
#include <vector>
#include <cstdio>
#include <chrono>
#include <algorithm>
#include <cmath>
#include <queue>

int main(int argc, char** argv) {
    FILE* f = fopen(argv[1], "rb");
    int32_t n;
    fread(&n, 4, 1, f);
    std::vector<double> C(n * (size_t)n);
    fread(C.data(), 8, n * (size_t)n, f);
    fclose(f);

    auto t0 = std::chrono::high_resolution_clock::now();

    // Scale costs to integers (distances in [0, sqrt(2)], scale by 1e7)
    const double SCALE = 1e7;
    std::vector<long long> cost(n * (size_t)n);
    long long Cmax = 1;
    for (size_t i = 0; i < cost.size(); ++i) {
        cost[i] = (long long)std::llround(C[i] * SCALE);
        if (cost[i] > Cmax) Cmax = cost[i];
    }

    // epsilon-scaling push-relabel / cost scaling for assignment
    // Duals p[j] (column prices), integer.
    std::vector<long long> price(n, 0);
    std::vector<int> owner(n, -1);      // col -> row
    std::vector<int> match(n, -1);      // row -> col

    auto reduced = [&](int i, int j, long long eps) -> long long {
        return cost[(size_t)i * n + j] + price[j]; // we'll keep eps outside
    };

    // For each epsilon phase, refine a partial matching via Dijkstra (successive shortest paths)
    // with reduced costs, admissible edges of reduced cost < eps are "free"? 
    // Simpler: just run SSP once with integer reduced costs using a Dial isn't easy for large range.
    // Use binary heap Dijkstra. n=600, n augmentations, each Dijkstra on dense graph with heap
    // of edges that improve. Same complexity issue.
    //
    // FAST PATH for 2D: we don't have coordinates here.
    // Use Jonker-Volgenant column reduction + augmenting with a HEAP instead of scan.

    std::vector<long long> v(n, 0); // dual col, integer
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<int> pred(n);
    std::vector<long long> dist(n);
    std::vector<char> scanned(n);
    const long long INF = (1LL<<62);

    // init duals by column min
    for (int j = 0; j < n; ++j) {
        long long mn = cost[j];
        int im = 0;
        for (int i = 1; i < n; ++i) {
            long long h = cost[(size_t)i * n + j];
            if (h < mn) { mn = h; im = i; }
        }
        v[j] = mn;
        if (rowsol[im] == -1) { rowsol[im] = j; colsol[j] = im; }
    }

    // heap Dijkstra augmentations for free rows
    struct Node { long long d; int j; bool operator<(const Node& o) const { return d > o.d; } };

    int matched = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] != -1) matched++;

    for (int s = 0; s < n; ++s) {
        if (rowsol[s] != -1) continue;
        std::priority_queue<Node> pq;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);
        for (int j = 0; j < n; ++j) {
            long long dj = cost[(size_t)s * n + j] - v[j];
            dist[j] = dj;
            pred[j] = s;
            pq.push({dj, j});
        }
        int sink = -1;
        while (!pq.empty()) {
            auto [dj, jmin] = pq.top(); pq.pop();
            if (dj != dist[jmin] || scanned[jmin]) continue;
            scanned[jmin] = 1;
            if (colsol[jmin] == -1) { sink = jmin; break; }
            int i = colsol[jmin];
            long long base = dist[jmin] - v[jmin]; // nd = dist[jmin] + cost[i,j] - v[j]  but dual of row?
            // reduced: nd = dist[jmin] + (cost[i,j] - v[j]) - (cost[i, jmin] - v[jmin])
            //        = dist[jmin] - cost[i,jmin] + v[jmin] + cost[i,j] - v[j]
            long long cijmin = cost[(size_t)i * n + jmin];
            for (int j = 0; j < n; ++j) if (!scanned[j]) {
                long long nd = dist[jmin] + cost[(size_t)i * n + j] - cijmin - v[j] + v[jmin];
                if (nd < dist[j]) {
                    dist[j] = nd;
                    pred[j] = i;
                    pq.push({nd, j});
                }
            }
        }
        if (sink < 0) { fprintf(stderr, "fail\n"); return 1; }
        long long delta = dist[sink];
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += delta - dist[j];
        int j = sink;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int next = rowsol[i];
            rowsol[i] = j;
            if (i == s) break;
            j = next;
        }
    }

    auto t1 = std::chrono::high_resolution_clock::now();
    fprintf(stderr, "time_ms %.3f matched_init %d\n",
            std::chrono::duration<double, std::milli>(t1 - t0).count(), matched);
    FILE* o = fopen(argv[2], "wb");
    fwrite(rowsol.data(), 4, n, o);
    fclose(o);
    return 0;
}
