// Network simplex for the assignment / transportation problem on a complete
// bipartite graph, following LEMON NetworkSimplexSimple + BlockSearchPivotRule
// closely enough to reproduce POT's basic solution for uniform weights.
//
// Arc id: forward arc (i -> j) has id = i * m + j.  (POT FullBipartiteDigraph)
// Artificial arcs: one per supply/demand node to a root, ids starting at n*m.
//
// We implement the classic network simplex:
//   - spanning tree of n+m-1 arcs (plus root connections making n+m arcs with root)
//   - BlockSearch pivot: scan arcs in contiguous blocks, pick the most violating
//   - leaving arc: first saturated arc on the cycle (LEMON uses the arc with
//     minimum residual in the appropriate direction; ties broken by tree index)
//
// Reference: LEMON network_simplex_simple.h (BSD), Bonneel et al. / POT.

#include <cstdint>
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <limits>

using namespace std;

struct Solver {
    int n, m;          // sources, targets
    int N;             // n + m  (nodes excluding root) 
    long long n_arcs;  // n * m forward arcs
    const double* cost; // row-major n*m
    const double* supply; // a[0..n), then we use b
    const double* demand;

    // Tree: parent pointers over nodes 0..n+m (root = n+m)
    // node id: sources 0..n-1, targets n..n+m-1, root n+m
    int root;
    int n_nodes; // n+m+1

    vector<int> parent;     // parent node
    vector<int> parent_arc; // arc connecting node to parent (forward arc id, or artificial)
    vector<int> depth;
    vector<int> thread;     // preorder thread successor
    vector<int> rev_thread;
    vector<int> succ_num;   // number of successors
    vector<double> flow;    // flow on the arc to parent? stored per node: flow of parent arc
    vector<double> pi;      // node potential. reduced cost of arc i->j is cost - pi[i] + pi[target]
    vector<char> forward;   // orientation of parent arc: 1 if parent arc is directed toward parent? 

    // artificial arc ids: for source i, art = n_arcs + i (from root to source, carrying supply)
    // for target j, art = n_arcs + n + j (from target to root, carrying demand)
    // LEMON's convention differs; we only need a correct optimal basis, then we'll
    // compare. If basis doesn't match we'll adjust tie breaks.

    int ART_SRC(int i) const { return (int)n_arcs + i; }
    int ART_TGT(int j) const { return (int)n_arcs + n + j; }

    double arc_cost(int arc) const {
        if (arc < n_arcs) return cost[arc];
        return 0.0; // artificial
    }

    void init_tree() {
        n_nodes = n + m + 1;
        root = n + m;
        parent.assign(n_nodes, root);
        parent_arc.assign(n_nodes, -1);
        depth.assign(n_nodes, 1);
        depth[root] = 0;
        flow.assign(n_nodes, 0.0);
        pi.assign(n_nodes, 0.0);
        forward.assign(n_nodes, 1);
        thread.assign(n_nodes, 0);
        rev_thread.assign(n_nodes, 0);
        succ_num.assign(n_nodes, 1);
        succ_num[root] = n_nodes;

        // initial basis: all nodes connected to root by artificial arcs
        // flow on source artificial = supply (root -> source), on target = demand (target -> root)
        for (int i = 0; i < n; ++i) {
            parent[i] = root;
            parent_arc[i] = ART_SRC(i);
            flow[i] = supply[i];
            forward[i] = 0; // arc is root -> source, parent is root, so arc is directed from parent to node
            pi[i] = 0.0;
        }
        for (int j = 0; j < m; ++j) {
            int node = n + j;
            parent[node] = root;
            parent_arc[node] = ART_TGT(j);
            flow[node] = demand[j];
            forward[node] = 1; // arc is target -> root, directed from node to parent
            pi[node] = 0.0;
        }
        // thread: root, then sources, then targets
        // preorder: root, 0, 1, ..., n-1, n, ..., n+m-1
        thread[root] = 0;
        for (int i = 0; i < n + m - 1; ++i) thread[i] = i + 1;
        thread[n + m - 1] = root;
        for (int i = 0; i < n_nodes; ++i) rev_thread[thread[i]] = i;
        // succ_num of root already n_nodes; children have 1
    }

    // reduced cost of forward arc i*m+j: c_ij - pi[i] + pi[n+j]
    // entering if reduced cost < -eps (we can send flow source->target to improve)
    // LEMON also considers reverse, but our graph is directed source->target only
    // (transportation problem). Artificial arcs are only in the tree.

    static constexpr double EPS = 1e-12;

    // Block search state
    long long next_arc = 0;
    int block_size;
    long long dummy_arc; // sentinel = n_arcs

    int find_entering() {
        // Scan a block of arcs, return the one with most negative reduced cost, or -1
        long long start = next_arc;
        long long cnt = 0;
        int best = -1;
        double best_rc = -EPS;
        int limit = block_size;
        while (cnt < limit) {
            if (next_arc >= n_arcs) next_arc = 0;
            int arc = (int)next_arc;
            int i = arc / m;
            int j = arc - i * m;
            double rc = cost[arc] - pi[i] + pi[n + j];
            if (rc < best_rc) { best_rc = rc; best = arc; }
            next_arc++;
            cnt++;
            if (next_arc == start) break; // full cycle
        }
        // LEMON block search: if a candidate was found, return it (not necessarily most negative
        // in the block — the FIRST eligible, actually, in some versions). 
        // POT BlockSearch returns the first violating arc in the block, not the min.
        // Let me check by also offering a first-eligible variant via a flag. For now return best (Dantzig in block).
        return best;
    }

    int find_entering_first() {
        long long start = next_arc;
        int scanned = 0;
        while (scanned < block_size) {
            if (next_arc >= n_arcs) next_arc = 0;
            int arc = (int)next_arc++;
            int i = arc / m;
            int j = arc - i * m;
            double rc = cost[arc] - pi[i] + pi[n + j];
            if (rc < -EPS) return arc;
            scanned++;
            if (next_arc == start) break;
        }
        return -1;
    }

    // Find the cycle created by adding entering arc (src -> tgt) and the leaving arc.
    // Walk up from source node and target node to root, find apex.
    // The leaving arc is the minimum-residual tree arc in the direction flow is decreased.
    // Sending flow along source->target increases flow on tree arcs oriented against the path
    // from source up to apex, and decreases flow on tree arcs oriented with the path from target up to apex.
    //
    // Orientation: forward[node]==1 means parent arc is directed node -> parent (flow toward parent).
    // forward[node]==0 means parent arc is directed parent -> node.
    //
    // Adding forward arc source->target: flow goes source up to apex, then down to target.
    // On the source side (nodes from source up to but not including apex):
    //   if we need to send flow FROM node TOWARD parent (up), we use the parent arc in the up direction.
    //   Residual capacity up:
    //     if forward[node]==1 (arc already node->parent), residual is +inf (can increase)
    //     if forward[node]==0 (arc parent->node), residual is flow[node] (can decrease to 0)
    // On the target side (from apex down to target), equivalently walking from target up to apex,
    // sending flow DOWN means opposite of up:
    //   residual down = inf if forward==0 (arc parent->node, increasing it sends down)
    //                 = flow if forward==1 (arc node->parent, decreasing it sends down)

    struct Leave { int node; double delta; }; // leaving arc is parent_arc[node], delta is flow change

    Leave find_leaving(int src, int tgt) {
        // compute depths and walk
        vector<int> up_s, up_t;
        int a = src, b = n + tgt;
        while (depth[a] > depth[b]) { up_s.push_back(a); a = parent[a]; }
        while (depth[b] > depth[a]) { up_t.push_back(b); b = parent[b]; }
        while (a != b) {
            up_s.push_back(a); a = parent[a];
            up_t.push_back(b); b = parent[b];
        }
        int apex = a;
        double delta = numeric_limits<double>::infinity();
        int leave = -1; // node whose parent arc leaves
        // source side: residual for upward flow
        for (int node : up_s) {
            double res;
            if (forward[node]) res = numeric_limits<double>::infinity(); // can increase
            else res = flow[node]; // decrease
            // tie break: LEMON picks the last minimum (closest to apex) or first?
            // We'll pick the one closest to the entering join that is minimum, preferring later (closer to apex)
            if (res < delta - 1e-15 || (res <= delta + 1e-15 && true)) {
                if (res < delta - 1e-15 || leave == -1) { delta = res; leave = node; }
                else if (fabs(res - delta) <= 1e-15) { delta = res; leave = node; } // later = closer to apex
            }
        }
        // target side: residual for downward flow
        for (int node : up_t) {
            double res;
            if (!forward[node]) res = numeric_limits<double>::infinity();
            else res = flow[node];
            if (res < delta - 1e-15) { delta = res; leave = node; }
            else if (fabs(res - delta) <= 1e-15) { delta = res; leave = node; }
        }
        if (leave < 0) { delta = 0; } // shouldn't happen
        return {leave, delta};
    }

    void pivot(int enter_arc, int src, int tgt) {
        Leave L = find_leaving(src, tgt);
        double delta = L.delta;
        if (!isfinite(delta)) return; // unbounded, shouldn't happen
        // update flows along cycle
        vector<int> up_s, up_t;
        int a = src, b = n + tgt;
        while (depth[a] > depth[b]) { up_s.push_back(a); a = parent[a]; }
        while (depth[b] > depth[a]) { up_t.push_back(b); b = parent[b]; }
        while (a != b) { up_s.push_back(a); a = parent[a]; up_t.push_back(b); b = parent[b]; }
        for (int node : up_s) {
            if (forward[node]) flow[node] += delta;
            else flow[node] -= delta;
        }
        for (int node : up_t) {
            if (forward[node]) flow[node] -= delta;
            else flow[node] += delta;
        }
        // if delta==0, degenerate pivot: still update tree if leaving arc is not the entering
        int leave_node = L.node;
        if (leave_node < 0) return;
        // update tree structure: remove parent arc of leave_node, add enter_arc
        // This is the delicate part. For a correct OPTIMAL solution (not necessarily same basis),
        // a simpler approach: if we only care about the final flow values on real arcs, we can
        // maintain flow in a dense/sparse map and update tree with parent pointers only,
        // recomputing depth/thread when needed.
        update_tree(enter_arc, src, tgt, leave_node);
    }

    void update_tree(int enter_arc, int src, int tgt, int leave_node) {
        // Rehang the subtree. Standard network simplex tree update.
        // The entering arc connects src (source node) to tgt_node = n+tgt.
        // One endpoint is in the subtree of leave_node, the other isn't.
        int tgt_node = n + tgt;
        // Determine which side leave_node is on by checking if leave is ancestor-side of src or tgt.
        auto is_ancestor = [&](int anc, int node) {
            while (node != root && node != anc) node = parent[node];
            return node == anc;
        };
        // The subtree being rehung is the component containing the endpoint on the leave side.
        // After removing leave_node's parent arc, the subtree rooted at leave_node is detached.
        // The entering arc reconnects it. The new parent of the subtree root (leave_node) becomes
        // the other endpoint of the entering arc, IF leave_node is in the subtree that contains
        // one endpoint. Actually leave_node is on the cycle, so leave_node is an ancestor of one
        // endpoint (src or tgt_node) or is that endpoint. The subtree root that gets a new parent
        // is leave_node, and its new parent is the endpoint NOT in its subtree, connected via the
        // path... This is getting error-prone.
        //
        // SIMPLER correct approach for assignment (uniform): don't maintain a general tree update.
        // Use the fact that for equal supplies the optimal flow is a permutation, and network
        // simplex degenerately pivots zero-flow arcs. The POSITIVE flow is the permutation.
        // We already can compute that. The question is only the basis.
        //
        // Given time, implement a well-known correct tree update from the
        // "Network Flows" (Ahuja) description:
        //   Let the entering arc be (k, l). The leaving arc is (p, q) with q child of p.
        //   The subtree rooted at q is reattached under the other end.
        // We'll identify q = leave_node, p = parent[q].
        // New parent of q is the cycle node on the other side, and the arc is the entering arc
        // only if q is src or tgt_node. Otherwise the entering arc is deeper and the whole
        // path from q down to the endpoint reverses.
        //
        // Path reversal implementation:
        int q = leave_node;
        // find which endpoint is in subtree of q
        bool src_in = is_ancestor(q, src) || q == src;
        int in_end = src_in ? src : tgt_node;      // endpoint inside subtree
        int out_end = src_in ? tgt_node : src;     // endpoint outside
        // collect path from in_end up to q (inclusive)
        vector<int> path;
        for (int x = in_end; x != q; x = parent[x]) path.push_back(x);
        path.push_back(q);
        // reverse parent pointers along path
        // new parent of in_end is out_end via enter_arc
        // new parent of path[t] is path[t-1] (old child direction) 
        // flow and forward orientation flip for reversed arcs
        // First, record old parent arcs
        vector<int> old_parent(path.size()), old_parc(path.size());
        vector<double> old_flow(path.size());
        vector<char> old_fwd(path.size());
        for (size_t t = 0; t < path.size(); ++t) {
            old_parent[t] = parent[path[t]];
            old_parc[t] = parent_arc[path[t]];
            old_flow[t] = flow[path[t]];
            old_fwd[t] = forward[path[t]];
        }
        // in_end (path[0]) now hangs off out_end via enter_arc
        parent[in_end] = out_end;
        parent_arc[in_end] = enter_arc;
        // orientation: enter arc is directed src -> tgt_node
        // forward[node]=1 means arc directed node -> parent
        // if in_end == src and out_end == tgt_node, arc src->tgt is node->parent, forward=1
        // if in_end == tgt_node and out_end == src, arc src->tgt is parent->node, forward=0
        if (in_end == src) forward[in_end] = 1;
        else forward[in_end] = 0;
        // flow on entering arc equals delta, which is the flow that was on the leaving arc
        // After pivot, flow on entering arc is delta (the amount we sent). 
        // We stored delta as the removed flow. Retrieve from old flow of q if it was the saturated one.
        // The flow pushed equals the old residual which equals old flow of leaving arc if it was saturated.
        // We need the delta. It is old_flow of q if that arc was the one decreased to 0.
        // Both orientations: the decreased arc had flow == delta. q's old flow was delta if it was binding,
        // which it is (we chose it as min). If residual was inf we wouldn't leave. So old_flow[last] == delta
        // only if q's arc was decreased. q is on the path, its old flow is old_flow.back().
        // The entering arc receives that delta.
        flow[in_end] = old_flow.back();
        // reverse intermediate
        for (size_t t = 1; t < path.size(); ++t) {
            int node = path[t];
            int child = path[t - 1];
            parent[node] = child;
            parent_arc[node] = old_parc[t - 1];
            flow[node] = old_flow[t - 1];
            // orientation flips relative to old child's orientation
            // old: parent_arc[child] connected child to old parent (which is node, if path is consistent)
            // forward[child]==1 meant arc directed child -> its parent.
            // Now node’s parent is child, so the same arc is directed (child -> node) i.e. parent -> node if forward was 1,
            // so new forward (node -> parent) is the opposite.
            forward[node] = !old_fwd[t - 1];
        }
        // recompute depth, thread, succ_num from scratch (n=600, pivots maybe a few thousand: fine)
        recompute_tree_index();
        // recompute potentials: pi[child] = pi[parent] +/- cost
        // reduced cost of every tree arc is 0.
        // If forward[node]==1, arc node->parent has cost c, rc = c - pi[node] + pi[parent] = 0
        //   => pi[node] = c + pi[parent]
        // If forward[node]==0, arc parent->node, rc = c - pi[parent] + pi[node] = 0
        //   => pi[node] = pi[parent] - c
        vector<int> order;
        order.reserve(n_nodes);
        int x = thread[root];
        while (x != root) { order.push_back(x); x = thread[x]; }
        for (int node : order) {
            int p = parent[node];
            int arc = parent_arc[node];
            double c = (arc < n_arcs && arc >= 0) ? cost[arc] : 0.0;
            if (forward[node]) pi[node] = pi[p] + c;
            else pi[node] = pi[p] - c;
        }
    }

    void recompute_tree_index() {
        // DFS from root to set depth, thread, succ_num
        vector<vector<int>> children(n_nodes);
        for (int i = 0; i < n_nodes; ++i) if (i != root) children[parent[i]].push_back(i);
        // stable order: sort children by node id to have a deterministic thread (affects tie breaks!)
        for (auto& ch : children) sort(ch.begin(), ch.end());
        depth[root] = 0;
        succ_num[root] = 1;
        vector<int> pre;
        pre.reserve(n_nodes);
        // iterative dfs
        vector<int> st = {root};
        vector<int> iti(n_nodes, 0);
        vector<char> entered(n_nodes, 0);
        while (!st.empty()) {
            int u = st.back();
            if (!entered[u]) { entered[u] = 1; pre.push_back(u); }
            auto& ch = children[u];
            if (iti[u] < (int)ch.size()) {
                int v = ch[iti[u]++];
                depth[v] = depth[u] + 1;
                st.push_back(v);
            } else {
                succ_num[u] = 1;
                for (int v : ch) succ_num[u] += succ_num[v];
                st.pop_back();
            }
        }
        for (size_t i = 0; i < pre.size(); ++i) {
            thread[pre[i]] = pre[(i + 1) % pre.size()];
            rev_thread[pre[(i + 1) % pre.size()]] = pre[i];
        }
    }

    int solve(bool first_eligible) {
        init_tree();
        recompute_tree_index();
        block_size = max(1, (int)sqrt((double)n_arcs));
        // LEMON default block size is often 1000 or based on arc count. We'll try a few.
        next_arc = 0;
        int stagnant = 0;
        int max_iter = 1000000;
        int iter = 0;
        int since_improve = 0;
        for (; iter < max_iter; ++iter) {
            int arc = first_eligible ? find_entering_first() : find_entering();
            if (arc < 0) {
                // completed a block with nothing. If we've scanned all arcs, optimal.
                // find_entering only scans one block. Loop until a full pass finds nothing.
                stagnant++;
                if ((long long)stagnant * block_size >= n_arcs) break;
                continue;
            }
            stagnant = 0;
            int src = arc / m;
            int tgt = arc - src * m;
            pivot(arc, src, tgt);
        }
        return iter;
    }

    void extract(double* G) {
        memset(G, 0, sizeof(double) * n * m);
        for (int node = 0; node < n + m; ++node) {
            int arc = parent_arc[node];
            if (arc >= 0 && arc < n_arcs && flow[node] > 1e-15) {
                G[arc] += flow[node];
            }
        }
        // NOTE: flow on non-parent arcs is zero in a basic solution. All positive flow is on tree arcs.
        // But our flow accounting might have flow on arcs that are no longer parent arcs — we only
        // store flow on parent arcs, and when we reverse we move flow. Real arcs not in the tree have 0.
        // This is correct IF flow updates are correct.
    }
};

int main(int argc, char** argv) {
    FILE* f = fopen(argv[1], "rb");
    int32_t n;
    fread(&n, 4, 1, f);
    vector<double> a(n), b(n), C(n * (size_t)n);
    fread(a.data(), 8, n, f);
    fread(b.data(), 8, n, f);
    fread(C.data(), 8, n * (size_t)n, f);
    fclose(f);
    Solver S;
    S.n = n; S.m = n; S.n_arcs = (long long)n * n;
    S.cost = C.data(); S.supply = a.data(); S.demand = b.data();
    auto t0 = chrono::high_resolution_clock::now();
    int it = S.solve(true);
    auto t1 = chrono::high_resolution_clock::now();
    fprintf(stderr, "iters %d time_ms %.3f\n", it, chrono::duration<double, std::milli>(t1-t0).count());
    vector<double> G(n * (size_t)n);
    S.extract(G.data());
    FILE* o = fopen(argv[2], "wb");
    fwrite(G.data(), 8, n * (size_t)n, o);
    fclose(o);
    return 0;
}
