// Fast assignment via kNN-restricted successive shortest paths (Dijkstra with radix-ish heap).
// Input: int32 n, float64 a[n], b[n], float64 M[n*n] row-major.
// We build kNN from the cost matrix (partial select) and run SSP.
// If the resulting dual is not feasible for the full matrix, we expand k and retry.
#include <cstdint>
#include <vector>
#include <cstdio>
#include <algorithm>
#include <chrono>
#include <queue>
#include <cmath>
#include <cstring>

struct Result {
    std::vector<int> col_of_row;
    std::vector<double> u, v;
    bool ok;
};

static Result ssp(int n, const double* C, const std::vector<std::vector<int>>& nbr,
                  const std::vector<std::vector<double>>& nc) {
    Result R;
    R.col_of_row.assign(n, -1);
    R.u.assign(n, 0);
    R.v.assign(n, 0);
    R.ok = true;
    std::vector<int> row_of_col(n, -1), pred(n);
    std::vector<double> dist(n);
    std::vector<char> seen(n);
    const double INF = 1e100;
    struct Node { double d; int j; bool operator<(const Node& o) const { return d > o.d; } };
    for (int s = 0; s < n; ++s) {
        std::priority_queue<Node> pq;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        for (size_t t = 0; t < nbr[s].size(); ++t) {
            int j = nbr[s][t];
            double dj = nc[s][t] - R.u[s] - R.v[j];
            if (dj < dist[j]) { dist[j] = dj; pred[j] = s; pq.push({dj, j}); }
        }
        int sink = -1;
        while (!pq.empty()) {
            auto [dj, jmin] = pq.top(); pq.pop();
            if (dj > dist[jmin] + 1e-15 || seen[jmin]) continue;
            seen[jmin] = 1;
            if (row_of_col[jmin] == -1) { sink = jmin; break; }
            int i = row_of_col[jmin];
            double base = dist[jmin] - R.u[i] - R.v[jmin];
            for (size_t t = 0; t < nbr[i].size(); ++t) {
                int j = nbr[i][t];
                if (seen[j]) continue;
                double nd = dist[jmin] + nc[i][t] - R.u[i] - R.v[j];
                if (nd < dist[j] - 1e-15) {
                    dist[j] = nd; pred[j] = i; pq.push({nd, j});
                }
            }
        }
        if (sink < 0) { R.ok = false; return R; }
        double delta = dist[sink];
        R.u[s] += delta;
        for (int j = 0; j < n; ++j) if (seen[j]) {
            double dv = delta - dist[j];
            R.v[j] -= dv;
            int i = row_of_col[j];
            if (i >= 0) R.u[i] += dv;
        }
        int j = sink;
        while (true) {
            int i = pred[j];
            int prev = R.col_of_row[i];
            R.col_of_row[i] = j;
            row_of_col[j] = i;
            if (i == s) break;
            j = prev;
        }
    }
    return R;
}

int main(int argc, char** argv) {
    FILE* f = fopen(argv[1], "rb");
