                double red = row[j] - ui - R.v[j];
                if (red < minred) minred = red;
            }
        }
        best = std::move(R);
        if (minred >= -1e-7) break;
    }
    auto t2 = std::chrono::high_resolution_clock::now();
    fprintf(stderr, "knn_ms %.3f ssp_ms %.3f k %d ok %d\n",
            std::chrono::duration<double, std::milli>(t1 - t0).count(),
            std::chrono::duration<double, std::milli>(t2 - t1).count(),
            used, (int)best.ok);
    std::vector<double> G(n * (size_t)n, 0.0);
    double w = a[0];
    if (best.ok) {
        for (int i = 0; i < n; ++i) {
            int j = best.col_of_row[i];
            if (j >= 0) G[(size_t)i * n + j] = w;
        }
    }
    FILE* o = fopen(argv[2], "wb");
    fwrite(G.data(), 8, G.size(), o);
    fclose(o);
    return 0;
}
