#include <cstdint>
#include <vector>
#include <algorithm>
#include <queue>
#include <cmath>
#include <cstring>
#include <cstdio>

// Solve uniform-weight EMD. M is n*n row-major float64.
// Writes n*n transport plan into G.
// Returns 0 on success (plan matches a basic optimal assignment), 1 on failure.

static bool ssp_k(int n, const double* C,
                  const std::vector<int>& nbr, int K,
                  std::vector<int>& col_of_row,
                  std::vector<double>& u, std::vector<double>& v) {
    col_of_row.assign(n, -1);
    u.assign(n, 0.0);
    v.assign(n, 0.0);
    std::vector<int> row_of_col(n, -1), pred(n);
    std::vector<double> dist(n);
    std::vector<char> seen(n);
    const double INF = 1e100;
    struct Node { double d; int j; bool operator<(const Node& o) const { return d > o.d; } };
    for (int s = 0; s < n; ++s) {
        std::priority_queue<Node> pq;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        const int* nb = nbr.data() + (size_t)s * K;
        const double* row = C + (size_t)s * n;
        double us = u[s];
        for (int t = 0; t < K; ++t) {
            int j = nb[t];
            double dj = row[j] - us - v[j];
            dist[j] = dj;
            pred[j] = s;
            pq.push({dj, j});
        }
        int sink = -1;
        while (!pq.empty()) {
            auto top = pq.top(); pq.pop();
            double dj = top.d; int jmin = top.j;
            if (dj > dist[jmin] + 1e-15 || seen[jmin]) continue;
            seen[jmin] = 1;
            if (row_of_col[jmin] < 0) { sink = jmin; break; }
            int i = row_of_col[jmin];
            const int* nbi = nbr.data() + (size_t)i * K;
            const double* rowi = C + (size_t)i * n;
            double ui = u[i];
            double base = dist[jmin] - ui;
            for (int t = 0; t < K; ++t) {
                int j = nbi[t];
                if (seen[j]) continue;
                double nd = base + rowi[j] - v[j];
                if (nd < dist[j] - 1e-15) {
                    dist[j] = nd;
                    pred[j] = i;
                    pq.push({nd, j});
                }
            }
        }
        if (sink < 0) return false;
        double delta = dist[sink];
        u[s] += delta;
        for (int j = 0; j < n; ++j) if (seen[j]) {
            double dv = delta - dist[j];
            v[j] -= dv;
            int i = row_of_col[j];
            if (i >= 0) u[i] += dv;
        }
        int j = sink;
        while (true) {
            int i = pred[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            if (i == s) break;
            j = prev;
        }
    }
    return true;
}

static bool dual_feasible(int n, const double* C,
                          const std::vector<double>& u, const std::vector<double>& v,
                          double tol) {
    for (int i = 0; i < n; ++i) {
        const double* row = C + (size_t)i * n;
        double ui = u[i];
        for (int j = 0; j < n; ++j) {
            if (row[j] - ui - v[j] < -tol) return false;
        }
    }
    return true;
}

extern "C" int solve_emd(int n, const double* a, const double* b, const double* M, double* G) {
    // kNN
    int K = std::min(n, 80);
    std::vector<int> nbr(n * (size_t)K);
    std::vector<int> order(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) order[j] = j;
        const double* row = M + (size_t)i * n;
        std::nth_element(order.begin(), order.begin() + K, order.end(),
                         [&](int j1, int j2) { return row[j1] < row[j2]; });
        // sort the K for stability (doesn't affect SSP correctness)
        std::sort(order.begin(), order.begin() + K, [&](int j1, int j2) { return row[j1] < row[j2]; });
        memcpy(nbr.data() + (size_t)i * K, order.data(), K * sizeof(int));
    }
    std::vector<int> col;
    std::vector<double> u, v;
    // try increasing k by using prefix of the sorted K list
    int ks[] = {30, 45, 60, 80};
    bool ok = false;
    int used = K;
    for (int k : ks) {
        if (k > K) break;
        // build prefix neighbor list of width k (compact)
        std::vector<int> nb(n * (size_t)k);
        for (int i = 0; i < n; ++i)
            memcpy(nb.data() + (size_t)i * k, nbr.data() + (size_t)i * K, k * sizeof(int));
        ok = ssp_k(n, M, nb, k, col, u, v);
        used = k;
        if (!ok) continue;
        if (dual_feasible(n, M, u, v, 1e-7)) { ok = true; break; }
        ok = false;
    }
    std::memset(G, 0, sizeof(double) * n * (size_t)n);
    if (!ok) return 1;
    double w = a[0];
    for (int i = 0; i < n; ++i) {
        int j = col[i];
        if (j >= 0) G[(size_t)i * n + j] = w;
    }
    return 0;
}
